WITH base AS (SELECT id, name, email, city, segment, signup_date, is_active, credit_limit, age, SUBSTRING(country, 1, 3) AS country_prefix, TRIM(country) AS clean_country FROM customers WHERE credit_limit < 7000) SELECT id, email, city, segment, signup_date, age, country_prefix, LEAD(age) OVER w_running AS next_age, LAG(age) OVER w_running AS prev_age, LEAD(credit_limit) OVER w_running AS next_credit_limit, ROW_NUMBER() OVER w_running AS event_seq, LAST_VALUE(age, TRUE) OVER w_running_2 AS last_known_age FROM base WINDOW w_running AS (PARTITION BY city, segment ORDER BY age, id), w_running_2 AS (PARTITION BY city ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
